<?php
namespace CloudHost247\Ovh\Reconciliation;use CloudHost247\Ovh\Services\ConnectionResolver;use WHMCS\Database\Capsule;use InvalidArgumentException;
final class ExistingServiceLinker
{private$r;function __construct(ConnectionResolver$r){$this->r=$r;}function search($endpointId,$query=''){$c=$this->r->endpoint($endpointId);$out=array();$locals=array_map(function($row){return(array)$row;},Capsule::table('tblhosting')->select('id','domain','dedicatedip')->limit(2000)->get()->all());$matcher=new ServiceMatcher();foreach(array('dedicated'=>(array)$c->get('/dedicated/server'),'vps'=>(array)$c->get('/vps'))as$f=>$names)foreach($names as$n)if($query===''||stripos($n,$query)!==false)$out[]=array('family'=>$f,'remote_service_name'=>(string)$n,'already_linked'=>Capsule::table('mod_cloudhost247_ovh_services')->where('endpoint_id',$endpointId)->where('remote_service_name',$n)->exists(),'suggestions'=>$matcher->rank((string)$n,$locals));return$out;}
 function preview($endpointId,$name,$family,$whmcsServiceId){$this->validate($name,$family);$hosting=Capsule::table('tblhosting')->where('id',(int)$whmcsServiceId)->first();if(!$hosting)throw new InvalidArgumentException('WHMCS service does not exist.');$path=$family==='vps'?'/vps/'.rawurlencode($name):'/dedicated/server/'.rawurlencode($name);$remote=$this->r->endpoint($endpointId)->get($path);return array('whmcs'=>array('id'=>$hosting->id,'client_id'=>$hosting->userid,'product_id'=>$hosting->packageid,'status'=>$hosting->domainstatus),'remote'=>$remote,'family'=>$family,'remote_service_name'=>$name);}
 function link($endpointId,$name,$family,$whmcsServiceId,$confirmed,$adminId){if(!$confirmed)throw new InvalidArgumentException('Explicit link confirmation is required.');$preview=$this->preview($endpointId,$name,$family,$whmcsServiceId);if(Capsule::table('mod_cloudhost247_ovh_services')->where('endpoint_id',$endpointId)->where('remote_service_name',$name)->where('whmcs_service_id','!=',$whmcsServiceId)->exists())throw new InvalidArgumentException('OVH service is already linked to another WHMCS service.');$before=Capsule::table('mod_cloudhost247_ovh_services')->where('whmcs_service_id',$whmcsServiceId)->first();Capsule::table('mod_cloudhost247_ovh_services')->updateOrInsert(array('whmcs_service_id'=>$whmcsServiceId),array('endpoint_id'=>$endpointId,'family'=>$family,'remote_service_name'=>$name,'status'=>'active','details_json'=>json_encode($preview['remote']),'last_synced_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')));Capsule::table('mod_cloudhost247_ovh_audit')->insert(array('admin_id'=>$adminId,'action'=>'service.link','target_type'=>'hosting','target_id'=>$whmcsServiceId,'before_json'=>json_encode($before),'after_json'=>json_encode(array('endpoint_id'=>$endpointId,'family'=>$family,'remote_service_name'=>$name)),'created_at'=>date('Y-m-d H:i:s')));return$preview;}
 private function validate($n,$f){if(!in_array($f,array('dedicated','vps'),true)||!preg_match('/^[A-Za-z0-9._-]{2,191}$/',$n))throw new InvalidArgumentException('Invalid OVH service identity.');}}
